using System.Text.Json;
using RaidClipPlugin.Config;
using RaidClipPlugin.Models;
using RaidClipPlugin.Services;
using Xunit;
namespace RaidClipPlugin.Tests;
public sealed class RpgTrinketTests
{
 readonly DateTimeOffset now=DateTimeOffset.Parse("2026-10-29T12:00:00Z");
 sealed class Low:IDuelRandom {public int NextInclusive(int min,int max)=>min;}
 sealed class High:IDuelRandom {public int NextInclusive(int min,int max)=>max;}
 static RpgProfile Wear(params string[] ids){var p=new RpgProfile{PlayerLevel=99};p.Health.CurrentHp=100;foreach(var id in ids){var item=RpgTrinketCatalog.Items().Single(i=>i.ItemId=="trinket_"+id);p.Inventory.Add(item);p.Equipment[p.Equipment.Count==0?EquipmentSlot.Trinket1:EquipmentSlot.Trinket2]=item.InstanceId;}return p;}
 [Fact] public void CatalogHasTwentyUniqueItemsAndPreservesOldSlots(){var c=new RpgConfig();c.Validate();RpgTrinketCatalog.AddMissing(c);Assert.Equal(20,c.DiveLoot.Items.Count(i=>i.ItemId.StartsWith("trinket_")));Assert.Equal(8,(int)EquipmentSlot.Belt);Assert.Equal(9,(int)EquipmentSlot.Trinket1);Assert.Equal(10,(int)EquipmentSlot.Trinket2);Assert.All(RpgTrinketCatalog.Items().GroupBy(i=>i.Rarity),g=>Assert.Equal(2,g.Count()));Assert.DoesNotContain(RpgTrinketCatalog.Items(),i=>i.Rarity==ItemRarity.Divine);}
 [Fact] public void BothDifferentTrinketsProcAndCooldownSurvivesReloadAndCopySwap(){var p=Wear("shell_chip","crab_tooth");Assert.Equal(65,RpgTrinketCatalog.Proc(100,false,p,new(),new Low(),now));Assert.Equal(0,RpgTrinketCatalog.Proc(100,false,p,new(),new Low(),now));p=JsonSerializer.Deserialize<RpgProfile>(JsonSerializer.Serialize(p))!;p.Inventory[0].InstanceId="new-copy";p.Equipment[EquipmentSlot.Trinket1]="new-copy";Assert.Equal(0,RpgTrinketCatalog.Proc(100,false,p,new(),new Low(),now.AddSeconds(1)));Assert.Equal(25,RpgTrinketCatalog.Proc(100,false,p,new(),new Low(),now.AddSeconds(4)));}
 [Fact] public void CriticalAndElementConditionsWorkWithoutWeapon(){var p=Wear("hunter_eye");Assert.Equal(0,RpgTrinketCatalog.Proc(100,false,p,new(),new Low(),now));Assert.Equal(90,RpgTrinketCatalog.Proc(100,true,p,new(),new Low(),now));p=Wear("shell_chip");Assert.Equal(50,RpgTrinketCatalog.Proc(100,false,p,new(){WaterDamage=50,ElementalDamage=50},new Low(),now));}
 [Fact] public void InventoryAndWrongSlotsDoNotGrantEffects(){var p=Wear("shell_chip");p.Equipment.Clear();Assert.Equal(0,RpgTrinketCatalog.Proc(100,true,p,new(),new Low(),now));p.Equipment[EquipmentSlot.Ring1]=p.Inventory[0].InstanceId;Assert.Equal(0,RpgTrinketCatalog.Proc(100,true,p,new(),new Low(),now));}
 [Fact] public void MissedProcHasNoCooldownAndDeadPlayersCannotTrigger(){var p=Wear("shell_chip");Assert.Equal(0,RpgTrinketCatalog.Proc(100,true,p,new(),new High(),now));Assert.Empty(p.Cooldowns);p.Health.CurrentHp=0;Assert.Equal(0,RpgTrinketCatalog.Proc(100,true,p,new(),new Low(),now));}
 [Fact] public void BossPipelineIncludesTrinketDamageOnce(){var c=new RpgConfig();var p=Wear("shell_chip");var first=RpgPassiveService.BossAttack(100,p,c,new Low(),now);var second=RpgPassiveService.BossAttack(100,p,c,new Low(),now);Assert.True(first.Damage>second.Damage);Assert.Equal(first.DirectDamage,second.DirectDamage);}
 [Fact] public void EveryTrinketHasAnObtainableSource(){var c=new RpgConfig();c.Validate();var guide=RpgLootLocations.Build(c);foreach(var item in RpgTrinketCatalog.Items()){var entry=guide.Single(i=>i.Id==item.ItemId);Assert.NotEmpty(entry.Sources);Assert.Contains(item.Description,entry.Effects);}}
 [Fact] public async Task EquipSupportsBothSlotsRejectsDuplicateDefinitionAndPersists(){var path=Path.Combine(Path.GetTempPath(),"trinket-test-"+Guid.NewGuid().ToString("N"));try{var store=new ViewerPointStore(path);var items=RpgTrinketCatalog.Items().Take(2).ToList();var duplicate=RpgTrinketCatalog.Items()[0];await store.ApplyRpgAsync("42","Otter","seed",a=>{a.Rpg.PlayerLevel=99;a.Rpg.Inventory.AddRange(items);a.Rpg.Inventory.Add(duplicate);return new(true);},default);var svc=new RpgProgressionService(store,new(){Enabled=true});Assert.True((await svc.EquipSelectionAsync("42","Otter","a",items[0].InstanceId,null,default)).Success);Assert.True((await svc.EquipSelectionAsync("42","Otter","b",items[1].InstanceId,null,default)).Success);Assert.False((await svc.EquipAsync("42","Otter","dup",duplicate.InstanceId,EquipmentSlot.Trinket2,default)).Success);Assert.False((await svc.EquipAsync("42","Otter","ring",items[0].InstanceId,EquipmentSlot.Ring1,default)).Success);var saved=(await new ViewerPointStore(path).GetProfileAsync("42",default)).Entry.Rpg;Assert.Equal(items[0].InstanceId,saved.Equipment[EquipmentSlot.Trinket1]);Assert.Equal(items[1].InstanceId,saved.Equipment[EquipmentSlot.Trinket2]);}finally{if(Directory.Exists(path))Directory.Delete(path,true);}}
}
